#include <WiFi.h>
#include <PubSubClient.h>
#include <freertos/FreeRTOS.h>

// Wi-Fi and MQTT Broker credentials
const char* ssid          = "YOUR_WIFI_SSID";
const char* password      = "YOUR_WIFI_PASSWORD";
const char* mqtt_server   = "broker.hivemq.com";
const int   mqtt_port     = 1883;
const char* mqtt_topic    = "esp32/telemetry";

WiFiClient espClient;
PubSubClient mqttClient(espClient);

// Shared resource and mutex handle for thread-safe cross-core communication
SemaphoreHandle_t dataMutex;
volatile int sharedSensorData = 0;

// ==========================================
// CORE 0 TASK: Wi-Fi & MQTT Communication
// ==========================================
void taskNetwork(void *pvParameters) {
  // Initialize Wi-Fi on Core 0
  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    vTaskDelay(500 / portTICK_PERIOD_MS);
  }

  mqttClient.setServer(mqtt_server, mqtt_port);

  for (;;) {
    // Reconnect to MQTT if connection drops
    if (!mqttClient.connected()) {
      String clientId = "ESP32Core0-" + String(random(0xffff), HEX);
      if (mqttClient.connect(clientId.c_str())) {
        mqttClient.publish("esp32/status", "Core 0 Connected");
      } else {
        vTaskDelay(2000 / portTICK_PERIOD_MS);
        continue;
      }
    }

    mqttClient.loop();

    // Safely retrieve the shared sensor reading from memory
    int sensorCopy = 0;
    if (xSemaphoreTake(dataMutex, pdMS_TO_TICKS(100)) == pdTRUE) {
      sensorCopy = sharedSensorData;
      xSemaphoreGive(dataMutex);

      // Publish payload
      char payload[32];
      snprintf(payload, sizeof(payload), "{\"value\":%d}", sensorCopy);
      mqttClient.publish(mqtt_topic, payload);
    }

    // Publish telemetry every 1 second
    vTaskDelay(1000 / portTICK_PERIOD_MS);
  }
}

// ==========================================
// CORE 1 TASK: Fast Sensor Acquisition / Processing
// ==========================================
void taskSensor(void *pvParameters) {
  for (;;) {
    // Simulate high-frequency or timing-sensitive sensor sampling
    int rawValue = random(100, 500);

    // Safely update the shared global variable
    if (xSemaphoreTake(dataMutex, pdMS_TO_TICKS(100)) == pdTRUE) {
      sharedSensorData = rawValue;
      xSemaphoreGive(dataMutex);
    }

    // Sample sensor every 100ms without being interrupted by Wi-Fi stack operations
    vTaskDelay(100 / portTICK_PERIOD_MS);
  }
}

void setup() {
  Serial.begin(115200);

  // Create Mutex for shared data protection across cores
  dataMutex = xSemaphoreCreateMutex();

  // Pin Network Task to Core 0
  xTaskCreatePinnedToCore(
    taskNetwork,    // Task function
    "NetworkTask",  // Task name
    8192,           // Stack size in bytes (Wi-Fi/MQTT needs ~8KB)
    NULL,           // Parameter
    1,              // Priority
    NULL,           // Task handle
    0               // Core ID (0)
  );

  // Pin Sensor Task to Core 1
  xTaskCreatePinnedToCore(
    taskSensor,     // Task function
    "SensorTask",   // Task name
    2048,           // Stack size in bytes
    NULL,           // Parameter
    1,              // Priority
    NULL,           // Task handle
    1               // Core ID (1)
  );
}

void loop() {
  // Delete main Arduino loop task to free resources (tasks manage execution)
  vTaskDelete(NULL);
}
